import React from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

export const options = {
  responsive: true,
  maintainAspectRatio: false,
  interaction: {
    mode: "index",
    intersect: false,
  },
  scales: {
    x: {
      grid: { display: false },
      ticks: {
        color: "#747b84",
        maxRotation: 0,
        autoSkip: true,
        maxTicksLimit: 8,
      },
    },
    y: {
      beginAtZero: true,
      grid: { color: "rgba(120, 130, 140, 0.12)" },
      ticks: {
        color: "#747b84",
        callback: (value) =>
          new Intl.NumberFormat("en-IN", {
            style: "currency",
            currency: "INR",
            notation: "compact",
            maximumFractionDigits: 1,
          }).format(value),
      },
    },
  },
  plugins: {
    legend: {
      position: "bottom",
      labels: {
        usePointStyle: true,
        pointStyle: "rectRounded",
        boxWidth: 8,
        padding: 18,
        color: "#505862",
      },
    },
    title: {
      display: true,
      text: "Invested amount vs current value",
      align: "start",
      color: "#39424e",
      font: { size: 15, weight: "600" },
      padding: { bottom: 18 },
    },
    tooltip: {
      callbacks: {
        label: (context) => {
          const value = Number(context.raw) || 0;
          return `${context.dataset.label}: ${new Intl.NumberFormat("en-IN", {
            style: "currency",
            currency: "INR",
            minimumFractionDigits: 2,
          }).format(value)}`;
        },
      },
    },
  },
};

export function VerticalGraph({ data }) {
  return (
    <div
      style={{ position: "relative", width: "100%", height: "320px", marginTop: "24px" }}
      role="img"
      aria-label="Bar chart comparing invested amount with current value for each holding"
    >
      <Bar options={options} data={data} />
    </div>
  );
}
